#!/bin/bash
# Sucht übriggebliebene du/ihr-Formen in Schülertexten
P='\b(du|dein\w*|dir|dich|ihr|euer\w*|eure\w*|euch|hast|kannst|musst|sollst|willst|bist|wirst|siehst|findest|brauchst|machst|weißt|lernst|arbeitest|übst|entscheidest|vergleichst|ermittelst|rechnest|ordnest|bereitest|erarbeitest|stellst|nimmst|kennst|schreibst|prüfst|gibst|nutzt|habt|könnt|müsst|seid|wollt|bearbeitet|lest|ordnet|legt|tragt|stellt|erarbeitet|verteilt|nehmt|schreibt|verbindet|bildet|prüft|haltet|überlegt|einigt|vergleicht|erklärt|geht|notiert|übertragt|fotografiert|beginnt|bringt|ergänzt|macht|wählt|lasst|Lies|Erkläre|Berechne|Wähle|Nenne|Ordne|Prüfe|Entwickle|Baue|Erstelle|Gestalte|Schlage|Lege|Begründe|Vergleiche|Beziehe|Notiere|Zeichne|Präsentiere|Teste|Ergänze|ergänze|Rechne|Erfrage|Überprüfe|Nutze|Beantworte|Stelle|Schreibe|Bearbeite|Gehe|Überlege|Übe|Trage|Verbinde|Bilde|Nimm|Bereite|Beurteile|Beschreibe|Recherchiere|Ermittle|Finde|Fasse|Halte|Gib|gib|Löse|Setze|Sammle|Markiere|Beachte|Arbeite|Mache|Frage|Zeige|Achte|Hake|Verteile|Bestimme|Entscheide|Lade|Melde|Sieh|Lerne|Wiederhole|Kreuze|Vermeide|Bewerte|Kennzeichne|Leite|Suche|Ändere|Ersetze|Erweitere|Fülle|Starte|Öffne|Klicke|Speichere|Schau|Schaue|Vergleiche|Rate|Erarbeite|Analysiere|Skizziere|Stell|Mach|Sag|Denk|Versuche|Probiere|Ergänz|Hilf|Warte|Merke|Merk|Begriffe)\b'
grep -n -E "$P" "$@" | grep -v -E "^\S+:[0-9]+:\s*#" | cut -c1-220
